package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func inputSplit() []uint16 {
	reader := bufio.NewReader(os.Stdin)
	line, _ := reader.ReadString('\n')
	line = strings.TrimSpace(line)
	parts := strings.Fields(line)

	result := make([]uint16, 0, len(parts))
	for _, p := range parts {
		n, _ := strconv.ParseUint(p, 10, 16)
		result = append(result, uint16(n))
	}
	return result
}

func determineB(v []uint16) *uint16 {
	var sum uint16
	for _, x := range v {
		sum += x
	}
	if sum%5 == 0 && sum != 0 {
		val := sum / 5
		return &val
	}
	return nil
}

func main() {
	res := determineB(inputSplit())
	if res != nil {
		fmt.Print(*res)
	} else {
		fmt.Print("-1")
	}
}

